mapper.select:
SELECT POS.ISSUE_PARTY_ID as issuePartyId, STR_TO_DATE(#{generateDate,jdbcType=VARCHAR},'%Y-%m-%d') as posDate, POS.PLAN_ASSET_ID as planAssetId, POS.ASSET_CODE as assetCode, POS.TOTAL_NUM as totalNum, POS.ISSUE_AMT as issueAmt, POS.UNINVEST_CASH as uninvestCash, POS.POS_NUM as posNum, POS.POS_AMT as posAmt, '01' status FROM CHB_BOT_AST_POS POS WHERE DATE_FORMAT(POS.POS_DATE,'%Y-%m-%d') = #{generateDate,jdbcType=VARCHAR}
and POS.ISCHL = '02'
and not exists (select 1 from CHB_BOT_AST_POS_SUB SUB where SUB.POS_DATE = POS.POS_DATE and SUB.PLAN_ASSET_ID = POS.PLAN_ASSET_ID and SUB.ASSET_CODE = POS.ASSET_CODE and SUB.SEND_STATUS in ('02','03'))

mapper.insert:
insert into CHB_BOT_AST_POS_SUB (REGIST_SEQNO,ISSUE_PARTY_ID,POS_DATE,PLAN_ASSET_ID,ASSET_CODE,TOTAL_NUM,ISSUE_AMT, UNINVEST_CASH,POS_NUM,POS_AMT,STATUS,SEND_STATUS,CHB_SUBMIT_DEADLINE,SUBMIT_DEADLINE, ORG_CODE, DEPT_CODE, CREATE_USER, CREATE_TIME, UPDATE_USER, UPDATE_TIME,STATUS_DATE) select F_GUID() REGIST_SEQNO, POS.ISSUE_PARTY_ID as ISSUE_PARTY_ID, STR_TO_DATE(#{generateDate,jdbcType=VARCHAR},'%Y-%m-%d') as POS_DATE, ifnull(PLANASSET.ASSET_CODE_OLD,PLANASSET.ASSET_CODE) as PLAN_ASSET_ID, ifnull(BOTASSET.ASSET_CODE_OLD,BOTASSET.ASSET_CODE) as ASSET_CODE, POS.TOTAL_NUM as TOTAL_NUM, POS.ISSUE_AMT as ISSUE_AMT, POS.UNINVEST_CASH as UNINVEST_CASH, POS.POS_NUM as POS_NUM, POS.POS_AMT as POS_AMT, '01' STATUS, '01' SEND_STATUS, #{chbSubmitDeadline,jdbcType=TIMESTAMP} CHB_SUBMIT_DEADLINE, #{submitDeadline,jdbcType=TIMESTAMP} SUBMIT_DEADLINE, POS.ORG_CODE ORG_CODE, POS.DEPT_CODE DEPT_CODE, 'system' CREATE_USER, NOW() CREATE_TIME, 'system' UPDATE_USER, NOW() UPDATE_TIME, #{statusDate,jdbcType=TIMESTAMP} STATUS_DATE FROM CHB_BOT_AST_POS POS LEFT JOIN CHB_ASSET_INFO PLANASSET ON PLANASSET.ASSET_CODE = POS.PLAN_ASSET_ID LEFT JOIN CHB_ASSET_INFO BOTASSET ON BOTASSET.ASSET_CODE = POS.ASSET_CODE WHERE DATE_FORMAT(POS.POS_DATE,'%Y-%m-%d') = #{generateDate,jdbcType=VARCHAR}
and POS.ISCHL = '02'
and not exists (select 1 from CHB_BOT_AST_POS_SUB SUB where SUB.POS_DATE = POS.POS_DATE and SUB.PLAN_ASSET_ID = POS.PLAN_ASSET_ID and SUB.ASSET_CODE = POS.ASSET_CODE and SUB.SEND_STATUS in ('02','03'))

mapper.delete:
delete from CHB_BOT_AST_POS_SUB


		DATE_FORMAT(POS_DATE,'%Y-%m-%d') = #{posDate,jdbcType=VARCHAR}


		and STATUS  = #{status,jdbcType=VARCHAR}


		and SEND_STATUS  = #{sendStatus,jdbcType=VARCHAR}
